<section class="npc-relationship-section" data-npc-development><h3>Un rapporto che lascia traccia</h3><p>Le esperienze possono cambiare fiducia, timori e legami. Una rassicurazione accolta può attenuare la paura senza cancellare ciò che il PNG conosce; affetto e lealtà possono crescere anche senza romanticismo.</p>
<div data-npc-aspirations><?php foreach($social['development']['aspirations']??[] as $wish): ?><article class="npc-offer"><h4><?=$wish['stance']==='desiderio'?'Una scelta desiderata':'Un limite dichiarato'?> · <?=$h(ucfirst($wish['family']))?></h4><p><?=$h($wish['summary'])?></p><blockquote><?=$h($wish['evidence'])?></blockquote><time><?=date('d/m/Y H:i',(int)$wish['created_at'])?></time></article><?php endforeach; ?></div>
<ol class="npc-memories" data-npc-development-story><?php foreach($social['development']['story']??[] as $episode): ?><li><time datetime="<?=date('c',(int)$episode['created_at'])?>"><?=date('d/m/Y H:i',(int)$episode['created_at'])?></time><strong><?=$episode['category']==='trauma'?'Un incontro che ha segnato il PNG':'Il legame è cambiato'?></strong><p><?=$h($episode['summary'])?></p></li><?php endforeach; ?></ol><p data-npc-development-empty<?=!empty($social['development']['story'])?' hidden':''?>>Nessun cambiamento emotivo condiviso è ancora documentato.</p></section>
<?php if(!$readOnly): ?><details class="npc-relationship-section"><summary>Preferenze del mio personaggio</summary><form class="ui-form" data-npc-action="preferences"><label>Età del personaggio · 0 se non dichiarata<input name="character_age" type="number" min="0" max="2000" value="<?=(int)$social['preferences']['character_age']?>" required></label><label><input type="checkbox" name="romance_enabled" <?php if($social['preferences']['romance_enabled']): ?>checked<?php endif; ?>> Consento trame romantiche con PNG adulti</label><label><input type="checkbox" name="intimacy_enabled" <?php if(!empty($social['preferences']['intimacy_enabled'])): ?>checked<?php endif; ?>> Consento relazioni adulte non esplicite in camere private</label><p>L’interesse non è garantito. Puoi ritirare questa disponibilità in qualsiasi momento. Senza età adulta dichiarata le trame romantiche sono disattivate.</p><button type="submit">Salva preferenze</button></form></details>
<section class="npc-relationship-section" data-companion-invitation><h3>Un incontro in privato</h3><p>Puoi invitare il PNG in una camera che hai affittato. La risposta dipende dalla sua disponibilità, dai suoi legami e dalla fiducia costruita con te.</p><button type="button" id="npc-invite-open">Invita in camera</button><div id="npc-invite-rooms" aria-live="polite"></div></section><?php endif; ?><section class="npc-relationship-section"><h3><?=$readOnly?'La storia di questo rapporto':'La nostra storia'?></h3><?php if(!$social['memories']): ?><p>Nessun ricordo condiviso ancora documentato.</p><?php else: ?><ol class="npc-memories"><?php foreach($social['memories'] as $memory): ?><li><time datetime="<?=date('c',(int)$memory['created_at'])?>"><?=date('d/m/Y H:i',(int)$memory['created_at'])?></time><strong><?=$h(ucfirst($memory['category']))?></strong><p><?=$h($memory['summary'])?></p><?php if($readOnly): ?><small><?=$memory['active']?'Memoria attiva':'Memoria disattivata'?> · <?=$memory['visible']?'Visibile al giocatore':'Riservata al PNG e allo staff'?></small><?php endif; ?><?php if($memory['source']==='interpreted'): ?><small>Interpretazione del dialogo, correggibile dallo staff.</small><?php endif; ?></li><?php endforeach; ?></ol><?php endif; ?></section>
<?php if(!$readOnly): ?><section class="npc-relationship-section"><h3>Accordi e <?=alphano_currency_html()?></h3><p>Devi al PNG: <?=(int)$social['debts']['player_owes']?> <?=alphano_currency_html()?> · Il PNG ti deve: <?=(int)$social['debts']['npc_owes']?> <?=alphano_currency_html()?>.</p>
<?php foreach($social['offers'] as $offer): ?><article class="npc-offer"><h4>Proposta · <?=(int)$offer['amount']?> <?=alphano_currency_html()?></h4><p><?=$h($offer['reason'])?></p><p><?=$h(['payment_to_npc'=>'Pagamento da te al PNG','payment_to_player'=>'Pagamento dal PNG a te','gift_to_npc'=>'Dono da te al PNG','gift_to_player'=>'Dono dal PNG a te','loan_to_player'=>'Prestito del PNG a te, da restituire','loan_to_npc'=>'Prestito da te al PNG, da restituire','repay_player'=>'Restituzione del PNG a te','repay_npc'=>'Restituzione del tuo debito al PNG'][$offer['kind']]??$offer['kind'])?> · scade alle <?=date('H:i',(int)$offer['expires_at'])?></p><div class="ui-row-actions"><?php foreach(['accept_offer'=>'Conferma movimento','reject_offer'=>'Rifiuta'] as $action=>$label): ?><form data-npc-action="<?=$action?>"><input type="hidden" name="offer_id" value="<?=(int)$offer['id']?>"><button type="submit"><?=$label?></button></form><?php endforeach; ?></div></article><?php endforeach; ?>
<?php if($sheet['npc_rules']['economy_enabled']&&$sheet['npc_rules']['accept_gifts']): ?><form class="ui-form" data-npc-action="gift"><label>Dona <?=alphano_currency_html()?> dal tuo saldo<input name="amount" type="number" min="1" max="<?=(int)$sheet['npc_rules']['max_amount']?>" value="1" required></label><button type="submit">Conferma dono al PNG</button><p>I doni non aumentano automaticamente fiducia, affetto o amore. Devi essere nella chat del PNG.</p></form><?php endif; ?>
<?php if($social['transactions']): ?><div class="ui-table-scroll"><table class="ui-data-table"><caption>I tuoi movimenti con il PNG</caption><thead><tr><th>Data</th><th>Causale</th><th><?=alphano_currency_html()?> sul tuo saldo</th></tr></thead><tbody><?php foreach($social['transactions'] as $transaction): ?><tr><td><?=date('d/m/Y H:i',(int)$transaction['created_at'])?></td><td><?=$h($transaction['reason'])?></td><td><?=((int)$transaction['player_delta']>0?'+':'').(int)$transaction['player_delta']?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</section><p data-npc-feedback role="status" aria-live="polite"></p><?php endif; ?>

